import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link, useNavigate } from "react-router-dom";
import { logout } from "../Features/UserSlice";
import "../Styles/Header.css";

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // ✅ نجيب المستخدم والدور من Redux بدلاً من localStorage
  const { user, isSuccess } = useSelector((state) => state.users);

  // 🔹 Logout مثل الأستاذة
  const handleLogout = async () => {
    dispatch(logout());
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  // 🔹 التحقق قبل فتح أي صفحة
  const handleProtectedClick = (path) => {
    if (!isSuccess || !user?.email) {
      alert("⚠️ You must log in to access this page.");
      navigate("/login");
    } else {
      navigate(path);
    }
  };

  return (
    <header className="header">
      {/* ✅ شعار UTAS Link */}
      <div className="brand">
        <div className="logo-circle">UL</div>
        <div className="brand-text">
          <span className="brand-main">UTAS</span>
          <span className="brand-accent">Link</span>
        </div>
      </div>

      {/* ✅ روابط التنقل */}
      <nav className="nav-links">
        <Link to="/">Home</Link>

        {/* 👩‍🎓 روابط الطالب */}
        {user?.role === "student" && (
          <>
            <span onClick={() => handleProtectedClick("/findjob")}>
              Find Job
            </span>
            <span onClick={() => handleProtectedClick("/myapplications")}>
              My Applications
            </span>
            <span onClick={() => handleProtectedClick("/userprofile")}>
              Profile
            </span>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* 🏢 روابط الشركة */}
        {user?.role === "company" && (
          <>
            <span onClick={() => handleProtectedClick("/companyprofile")}>
              Company Profile
            </span>
            <span onClick={() => handleProtectedClick("/postjob")}>
              Post Job
            </span>
            <span onClick={() => handleProtectedClick("/companyjobs")}>
              My Jobs
            </span>
            <span onClick={() => handleProtectedClick("/applicantsjob")}>
              Applicants
            </span>
            <span onClick={() => handleProtectedClick("/chatpage")}>Chat</span>
            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* 🚪 المستخدم غير المسجل */}
        {!user?.email && (
          <>
            <Link to="/login">Login</Link>
            <Link to="/user-register">Register</Link>
          </>
        )}
      </nav>
    </header>
  );
};

export default Header;
